//region Handle Form Submit
handleLoginRegisterSubmit = async function(evnt) {
  var email, err, password;
  log("handleLoginRegisterSubmit");
  evnt.preventDefault();
  email = emailInput.value;
  password = passwordInput.value;
  if (mode === "login") {
    try {
      await handleLoginSubmit(email, password);
    } catch (error1) {
      err = error1;
      console.error(err.message);
    }
    return;
  }
  if (mode === "register") {
    try {
      await handleRegisterSubmit(email);
    } catch (error1) {
      err = error1;
      console.error(err.message);
    }
    return;
  }
};

//###########################################################
handleRegisterSubmit = async function(email) {
  var err;
  log("handleRegisterSubmit");
  try {
    await register(email, globalThis.specialLinkName);
  } catch (error1) {
    err = error1;
    return indicateRegisterError(err);
  }
  setRegisterSuccess();
};

handleLoginSubmit = async function(email, password) {
  var err;
  log("handleLoginSubmit");
  try {
    await executeLogin(email, password);
  } catch (error1) {
    err = error1;
    return indicateLoginError(err);
  }
};

//endregion

//###########################################################
keyupOnErrorSuccess = function(evnt) {
  if (evnt.key === "Escape") {
    return;
  }
  if (evnt.key === "Enter") {
    return;
  }
  if (mode === "login-failure" || mode === "password-reset-failure" || mode === "password-reset-success") {
    setLoginState();
    return;
  }
  if (mode === "register-failure" || mode === "register-success") {
    setRegisterState();
    return;
  }
  console.error("leaveErrorSuccessStae -> illegal mode: " + mode);
};

//###########################################################
passwordResetClicked = async function() {
  var email, err;
  log("passwordResetClicked");
  passwordInput.value = "";
  email = emailInput.value;
  try {
    await requestPasswordReset(email);
  } catch (error1) {
    err = error1;
    return indicatePasswordResetError(err);
  }
  setPasswordResetRequestSuccess();
};

